test("consolidated figures scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "cap", "2.00");
  await ui.setSetting(pg_uma, "perm-settle", "steward");
  expect(await ui.addHoliday(pg_uma, "2026-04-03")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
  await ui.setSetting(pg_uma, "grace-A", "5");
  await ui.setSetting(pg_uma, "proof-threshold-B", "4.00");
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "7.50"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.35"}));
  expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "10.25", "note": ""})).toBe(true);
  await ui.setSetting(pg_uma, "pot", "33.33");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50"})).toBe(true);
  expect(await ui.generatePeriods(pg_uma, "2026-02-01", "2026-04-30")).toBe(3);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "terms": "20"}));
  const p_ada_2 = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B"}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "50.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "50.00"})).toBe(true);
  const c_ada_0_2 = ui.must(await ui.addClaim(pg_uma, p_ada_2, {"amount": "1.00", "date": "2026-03-01", "note": "n", "ref": "R-1"}));
  expect(await ui.periodAction(pg_uma, "2026-04", "close")).toBe(true);
  expect(await ui.addAlias(pg_uma, p_ada_2, "Al")).toBe(true);
  await ui.setSetting(pg_uma, "entry-date", "2026-03-01");
  await ui.setToday(pg_uma, "2026-05-12");
  expect(await ui.hold(pg_uma, p_ben, {"from": "2026-03-09", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-04-06")).toBe(true);
  await expect(pg_uma.getByTestId("summary-status-SETTLED-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("summary-status-VOID-count")).toHaveText("0");
